<script>
const homePage=document.getElementById('homePage');
const checkerPage=document.getElementById('checkerPage');
const holder=document.getElementById('stepHolder');
const modal=document.getElementById('refineModal');
const modalList=document.getElementById('modalList');
const doneButton=document.getElementById('doneButton');
let step=0, sex='', age='', query='', symptoms=[], selectedRefinements=[];
const refinements=['pounding headache','dull headache','migraine headache','severe headache','headache in back of head','headache in front of head','headache behind ears','headache on temples','one sided headache','tension headache','repeated headaches','sudden severe headache','headache in the morning','headache','None of the above'];
const bodySvg=`<svg class="body-svg" viewBox="0 0 270 460" aria-label="Body map">
<g fill="#cfdee1" stroke="#bdcdd1" stroke-width="2">
<ellipse cx="135" cy="33" rx="24" ry="31"/><path d="M119 60 Q135 53 151 60 L159 81 Q184 83 199 105 L220 157 Q226 171 218 178 Q210 184 204 173 L185 133 L198 186 Q205 215 184 228 L178 288 L194 373 Q198 392 188 398 Q178 404 171 385 L148 304 L142 390 L144 434 Q145 449 134 449 Q123 449 123 434 L118 390 L112 304 L89 386 Q83 404 73 398 Q64 393 69 374 L86 288 L81 228 Q61 215 68 186 L81 133 L62 173 Q56 184 48 178 Q41 171 47 157 L68 105 Q81 83 109 81Z"/>
<path d="M111 84 Q135 98 159 84 L154 160 Q135 180 116 160Z" fill="#dce8e9" stroke="none"/>
</g></svg>`;
function showChecker(){homePage.style.display='none';checkerPage.style.display='block';window.scrollTo(0,0);render()}
function showHome(){checkerPage.style.display='none';homePage.style.display='block';window.scrollTo(0,0)}
document.getElementById('navChecker').addEventListener('click',e=>{e.preventDefault();showChecker()});
document.getElementById('homeLogo').addEventListener('click',e=>{e.preventDefault();showHome()});
function setTabs(){document.querySelectorAll('.tab').forEach((t,i)=>t.classList.toggle('active',i===Math.min(step,4)))}
function render(){
 setTabs();
 if(step===0){holder.innerHTML=`<div class="intro"><h2><em>WebMD</em> Symptom Checker <small style="font-size:14px;color:#3283a6">WITH BODY MAP</small></h2><p>Identify possible conditions and treatment related to your symptoms.</p><div class="disclaimer-small">This tool does not provide medical advice. <a href="#" class="btn" id="additionalInfo">See additional information⌄</a></div></div>
 <div class="info-fields"><p class="note"></p><div class="fieldrow"><div class="field-group"><label>Age</label><input class="age" id="ageInput" type="text" inputmode="numeric" value="${age}" aria-label="Age"></div><div class="field-group"><label>Sex</label><div class="sexbuttons"><button class="btn ${sex==='Male'?'selected':''}" data-sex="Male">Male</button><button class="btn ${sex==='Female'?'selected':''}" data-sex="Female">Female</button></div></div></div><button class="primary continue-info btn" id="continueInfo" ${age&&sex?'':'disabled'}>Continue　›</button></div>`;
 const ageInput=document.getElementById('ageInput');ageInput.addEventListener('input',()=>{age=ageInput.value;document.getElementById('continueInfo').disabled=!(age&&sex)});
 document.querySelectorAll('[data-sex]').forEach(b=>b.onclick=()=>{sex=b.dataset.sex;render()});
 document.getElementById('continueInfo').onclick=()=>{if(age&&sex){step=1;render()}};
 document.getElementById('additionalInfo').onclick=e=>e.preventDefault();
 }else if(step===1){renderSymptoms()}
 else if(step===2){renderResults()}
 else if(step===3){renderDetails()}
 else {holder.innerHTML=`<div class="detail-step"><h2>Treatment Options</h2><p>Talk with your doctor about treatment options that may be right for you.</p><button class="secondary btn" onclick="step=3;render()">Previous</button></div>`}
}
function renderSymptoms(){
 holder.innerHTML=`<div class="step-content"><h2 class="symptom-title">What are your symptoms?</h2><input class="symptom-input" id="symptomInput" placeholder="Type your main symptom here" value="${query}">
 <div class="body-area">${bodySvg}<div class="body-tools"><button class="tool btn" title="Body map">↔</button><button class="tool btn">☷</button><button class="tool btn">SKIN</button></div></div>
 ${symptoms.length?`<div class="my-symptoms"><h3>My Symptoms</h3>${symptoms.map((s,i)=>`<div class="symptom-entry">${s}<button class="btn" data-remove="${i}">▤</button></div>`).join('')}</div>`:`<div class="empty-symptoms"><div class="empty-icon">☷</div><span>No symptoms added</span></div>`}
 <div class="suggestions" id="suggestions" style="display:none"></div></div>
 <div class="bottom-controls"><button class="secondary btn" id="previous"><span class="arrow">‹</span> Previous</button><button class="primary btn" id="continueSymptoms" ${symptoms.length?'':'disabled'}>Continue　›</button></div>`;
 const input=document.getElementById('symptomInput'), box=document.getElementById('suggestions');
 input.addEventListener('input',()=>{query=input.value;let q=query.toLowerCase().trim();if(q && ('headache'.includes(q)||q.includes('head'))){box.style.display='block';let opts=['headache in front of head','headache in back of head','headache on one side of head','headache','head edema','head swelling'];box.innerHTML=opts.map(x=>`<div class="suggestion"><span>${x}</span><button class="btn" data-add="${x}">ADD</button></div>`).join('');box.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{query='';openModal()})}else box.style.display='none'});
 document.getElementById('previous').onclick=()=>{step=0;render()};
 document.getElementById('continueSymptoms').onclick=()=>{if(symptoms.length){step=2;render()}};
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{symptoms.splice(+b.dataset.remove,1);render()});
}
function openModal(){modal.style.display='flex';selectedRefinements=[];renderModal()}
function renderModal(){modalList.innerHTML=refinements.map((r,i)=>`<label class="modal-option"><input type="checkbox" value="${r}" ${selectedRefinements.includes(r)?'checked':''}><span>${r}</span></label>`).join('');modalList.querySelectorAll('input').forEach(c=>c.onchange=()=>{if(c.checked){if(!selectedRefinements.includes(c.value))selectedRefinements.push(c.value)}else selectedRefinements=selectedRefinements.filter(x=>x!==c.value);doneButton.classList.toggle('enabled',selectedRefinements.length>0)})}
function closeModal(add){modal.style.display='none';if(add){let chosen=selectedRefinements.filter(x=>x!=='None of the above');if(!chosen.length)chosen=['headache'];chosen.forEach(x=>{if(!symptoms.includes(x))symptoms.push(x)})}query='';render()}
doneButton.onclick=()=>closeModal(true);
document.getElementById('skipButton').onclick=()=>closeModal(false);
